```go
package db

import (
	"flag"
	"firempq/db/cldb"
	"firempq/log"
	"os"
	"sync"

	. "firempq/api"
)

var database DataStorage = nil
var lock sync.Mutex

// UseLevigo is a flag to switch between goleveldb and levigo.
var UseLevigo = flag.Bool("levigo", false, "Use levigo instead of goleveldb")

// GetDatabase returns DataStorage singleton.
func GetDatabase() DataStorage {
	lock.Lock()
	defer lock.Unlock()
	return getDatabase()
}

func SetDatabase(ds DataStorage) {
	database = ds
}

func getDatabase() DataStorage {
	if database == nil {
		var err error
		if *UseLevigo {
			database, err = cldb.NewLevigoStorage("databasedir")
		} else {
			database, err = cldb.NewLevelDBStorage("databasedir")
		}
		if err != nil {
			log.Error("Cannot initialize FireMPQ database: %s", err)
			os.Exit(255)
		}
	}

	if database.IsClosed() {
		database = nil
		return getDatabase()
	}
	return database
}
