```go
package gradientdescent_test

import (
	"math"
	"testing"

	"github.com/yourusername/yourproject/optimizer/gradientdescent"
)

func TestGradientDescent(t *testing.T) {
	// Define a simple quadratic function: f(x) = x^2
	// The minimum is at x = 0
	f := func(x float64) float64 {
		return x * x
	}

	// Define the gradient: f'(x) = 2x
	gradient := func(x float64) float64 {
		return 2 * x
	}

	// Test parameters
	initialX := 10.0
	learningRate := 0.1
	maxIterations := 1000
	epsilon := 1e-6

	// Run gradient descent
	result, err := gradientdescent.GradientDescent(f, gradient, initialX, learningRate, maxIterations, epsilon)
	if err != nil {
		t.Fatalf("GradientDescent returned an error: %v", err)
	}

	// Check if the result is close to the expected minimum (x = 0)
	if math.Abs(result.X) > epsilon {
		t.Errorf("Expected x to be close to 0, got %v", result.X)
	}

	// Check if the function value is close to the expected minimum (f(0) = 0)
	if math.Abs(result.F) > epsilon {
		t.Errorf("Expected f(x) to be close to 0, got %v", result.F)
	}

	// Check if the number of iterations is within expected bounds
	if result.Iterations > maxIterations {
		t.Errorf("Expected iterations to be <= %d, got %d", maxIterations, result.Iterations)
	}
}

func TestGradientDescentConvergence(t *testing.T) {
	// Define a more complex function: f(x) = (x - 3)^2 + 1
	// The minimum is at x = 3, f(3) = 1
	f := func(x float64) float64 {
		return math.Pow(x-3, 2) + 1
	}

	// Define the gradient: f'(x) = 2(x - 3)
	gradient := func(x float64) float64 {
		return 2 * (x - 3)
	}

	// Test parameters
	initialX := 0.0
	learningRate := 0.1
	maxIterations := 1000
	epsilon := 1e-6

	// Run gradient descent
	result, err := gradientdescent.GradientDescent(f, gradient, initialX, learningRate, maxIterations, epsilon)
	if err != nil {
		t.Fatalf("GradientDescent returned an error: %v", err)
	}

	// Check if the result is close to the expected minimum (x = 3)
	if math.Abs(result.X-3) > epsilon {
		t.Errorf("Expected x to be close to 3, got %v", result.X)
	}

	// Check if the function value is close to the expected minimum (f(3) = 1)
	if math.Abs(result.F-1) > epsilon {
		t.Errorf("Expected f(x) to be close to 1, got %v", result.F)
	}
}

func TestGradientDescentLargeLearningRate(t *testing.T) {
	// Define a simple quadratic function: f(x) = x^2
	f := func(x float64) float64 {
		return x * x
	}

	// Define the gradient: f'(x) = 2x
	gradient := func(x float64) float64 {
		return 2 * x
	}

	// Test with a large learning rate that might cause divergence
	initialX := 1.0
	learningRate := 1.0
	maxIterations := 1000
	epsilon := 1e-6

	// Run gradient descent
	result, err := gradientdescent.GradientDescent(f, gradient, initialX, learningRate, maxIterations, epsilon)
	if err != nil {
		t.Fatalf("GradientDescent returned an error: %v", err)
	}

	// With a large learning rate, the algorithm might not converge
	// We just check that it doesn't panic and returns a result
	if result.X == 0 && result.F == 0 {
		t.Errorf("Expected non-zero result due to large learning rate, got x=%v, f=%v", result.X, result.F)
	}
}
