		}
	}()

	// Write the buffered content to the UI view
	go func() {
		io.Copy(v, &buf)
	}()

	if err := v.Focus(keyboardQueue); err != nil {
		ui.ShowErrorMessage(screen, keyboardQueue, closeView, err)
	}

	stream.Close()
	termbox.HideCursor()
	screen.Clear()
	screen.Sync()
}
