```go
package device

import (
	"sync"

	"github.com/tarm/serial"
)

type Manager struct {
	devices []*Conn
	mu      sync.RWMutex
}

func (m *Manager) AddDevice(name string) error {
	cfg := serial.Config{Name: name}
	conn := &Conn{
		device: cfg,
	}
	m.mu.Lock()
	m.devices = append(m.devices, conn)
	m.mu.Unlock()
	return nil
}

func (m *Manager) RemoveDevice(name string) error {
	m.mu.Lock()
	defer m.mu.Unlock()

	for i, conn := range m.devices {
		if conn.device.Name == name {
			m.devices = append(m.devices[:i], m.devices[i+1:]...)
			return nil
		}
	}
	return nil
}

type Conn struct {
	device serial.Config
