package ir

import (
	"testing"

	"github.com/tisp-lang/tisp/src/lib/core"
)

func TestNewSwitch(t *testing.T) {
	NewSwitch(0, []Case{NewCase(core.Nil, 1)})
}

func TestNewSwitchNoPattern(t *testing.T) {
	defer func() {
		if r := recover(); r == nil {
			t.Fail()
		}
	}()

	NewSwitch(0, []Case{})
}

func TestSwitchCompileToDict(t *testing.T) {
	NewSwitch(0, []Case{NewCase(core.Nil, 1)}).compileToDict()
}

func TestSwitchExpressionInFunction(t *testing.T) {
	// Create a simple function with a switch expression
	fn := NewFunction([]string{"x"}, []Expr{
		NewSwitch(
			NewVar("x"),
			[]Case{
				NewCase(core.Nil, NewInt(0)),
				NewCase(core.Int(1), NewInt(1)),
			},
		),
	})

	if fn == nil {
		t.Fatal("Expected non-nil function")
	}

	if len(fn.Params) != 1 || fn.Params[0] != "x" {
		t.Errorf("Expected params [x], got %v", fn.Params)
	}

	if len(fn.Body) != 1 {
		t.Errorf("Expected body length 1, got %d", len(fn.Body))
	}

	switchExpr, ok := fn.Body[0].(*Switch)
	if !ok {
		t.Fatalf("Expected body to be a Switch, got %T", fn.Body[0])
	}

	if switchExpr.Expr == nil {
		t.Error("Expected switch expression to be non-nil")
	}

	if len(switchExpr.Cases) != 2 {
		t.Errorf("Expected 2 cases, got %d", len(switchExpr.Cases))
	}
}
