	cmd.Env = os.Environ()

	cmd.Env = append(
		os.Environ(),
		fmt.Sprintf("SVN_URL=%s", repo.URL),
		fmt.Sprintf("SVN_REVISION=%d", repo.Revision),
	)

	if err := cmd.Run(); err != nil {
		return errors.Wrapf(err, "failed to execute %s", c.Command)
	}

	return nil
}
