// The time complexity is O(n), and O(1) additional space is needed.
func FindCelebrity(f [][]bool) int {
	candidate, checker := 0, 1 // checker starts at 1 'cause it's after start of diagonal (A<->A, B<->B, C<->C, ...)
	for checker < len(f) {
		if f[candidate][checker] {
			candidate, checker = checker, checker+1 // All candidates less then checker are not celebrity candidates.
		} else {
			checker++ // candidate is still a celebrity candidate but checker is not.
		}
	}
	for _, knowsSomeone := range f[candidate] { // Check if selected candidate is really a celebrity.
		if knowsSomeone {
			return -1
		}
	}
	return candidate
}
