```go
package graph

import (
	"encoding/json"
	"fmt"
)

// RSVPStatus represents the possible states of an invitation's RSVP.
type RSVPStatus string

const (
	RSVPNotReplied RSVPStatus = "not_replied"
	RSVPAttending  RSVPStatus = "attending"
	RSVPUnsure     RSVPStatus = "unsure"
	RSVPDeclined   RSVPStatus = "declined"
)

// Invitation represents a social invitation with object-oriented design.
type Invitation struct {
	Name       string
	ID         string
	RSVPStatus RSVPStatus
}

// NewInvitation creates a new Invitation instance.
func NewInvitation() *Invitation {
	return &Invitation{
		RSVPStatus: RSVPNotReplied,
	}
}

// ParseData populates the Invitation from a raw data map.
func (i *Invitation) ParseData(data map[string]interface{}) error {
	if name, ok := data["name"].(string); ok {
		i.Name = name
	} else {
		return fmt.Errorf("missing or invalid 'name' field")
	}

	if id, ok := data["id"].(string); ok {
		i.ID = id
	} else {
		return fmt.Errorf("missing or invalid 'id' field")
	}

	if rsvpStatus, ok := data["rsvp_status"].(string); ok {
		i.RSVPStatus = RSVPStatus(rsvpStatus)
	} else {
		return fmt.Errorf("missing or invalid 'rsvp_status' field")
	}

	return nil
}

// MarshalJSON implements custom JSON marshaling for Invitation.
func (i *Invitation) MarshalJSON() ([]byte, error) {
	type Alias Invitation
	return json.Marshal(&struct {
		RSVPStatus string `json:"rsvp_status"`
		*Alias
	}{
		RSVPStatus: string(i.RSVPStatus),
		Alias:      (*Alias)(i),
	})
}

// UnmarshalJSON implements custom JSON unmarshaling for Invitation.
func (i *Invitation) UnmarshalJSON(data []byte) error {
	type Alias Invitation
	aux := &struct {
		RSVPStatus string `json:"rsvp_status"`
		*Alias
	}{
		Alias: (*Alias)(i),
	}

	if err := json.Unmarshal(data, &aux); err != nil {
		return err
	}

	i.RSVPStatus = RSVPStatus(aux.RSVPStatus)
	return nil
}
