func TestLogoutHandler(t *testing.T) {
	setUp("/config/testing/handler_logout_url.yml")
	handler := http.HandlerFunc(LogoutHandler)

	tests := []struct {
		name     string
		url      string
		wantcode int
		wantLoc  string
	}{
		{"allowed", "http://myapp.example.com/login", http.StatusFound, "http://myapp.example.com/login"},
		{"allowed", "https://oauth2.googleapis.com/revoke", http.StatusFound, "https://oauth2.googleapis.com/revoke"},
		{"not allowed", "http://myapp.example.com/loginagain", http.StatusBadRequest, ""},
		{"not allowed", "http://google.com/", http.StatusBadRequest, ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			req, err := http.NewRequest("GET", "/logout?url="+tt.url, nil)
			if err != nil {
				t.Fatal(err)
			}
			rr := httptest.NewRecorder()
			handler.ServeHTTP(rr, req)
			if rr.Code != tt.wantcode {
				t.Errorf("LogoutHandler() = %v, want %v", rr.Code, tt.wantcode)
			}
			if tt.wantcode == http.StatusFound {
				loc := rr.Header().Get("Location")
				if loc != tt.wantLoc {
					t.Errorf("LogoutHandler() Location = %v, want %v", loc, tt.wantLoc)
				}
			}
		})
