// Config represents the application configuration
type Config struct {
	// Add fields as needed
}

// ConfigWriter handles writing configuration to files
type ConfigWriter struct {
	configPath string
}

// NewConfigWriter creates a new ConfigWriter instance
func NewConfigWriter(configPath string) *ConfigWriter {
	return &ConfigWriter{
		configPath: configPath,
	}
}

// WriteConfig writes the configuration to the specified path
func (cw *ConfigWriter) WriteConfig(config *Config) error {
	// Ensure directory exists
	dir := filepath.Dir(cw.configPath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}

	// Write config to file (simplified for this example)
	data, err := serializeConfig(config)
	if err != nil {
		return fmt.Errorf("failed to serialize config: %w", err)
	}

	if err := os.WriteFile(cw.configPath, data, 0644); err != nil {
		return fmt.Errorf("failed to write config file: %w", err)
	}

	return nil
}

// AddConfig adds a new configuration entry
func (cw *ConfigWriter) AddConfig(key string, value string) error {
	// Read existing config
	existing, err := cw.readConfig()
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to read existing config: %w", err)
	}

	// Add or update the key-value pair
	existing[key] = value

	// Write back
	return cw.writeConfig(existing)
}

// RemoveConfig removes a configuration entry by key
func (cw *ConfigWriter) RemoveConfig(key string) error {
	// Read existing config
	existing, err := cw.readConfig()
	if err != nil {
		if os.IsNotExist(err) {
			return nil // Nothing to remove
		}
		return fmt.Errorf("failed to read existing config: %w", err)
	}

	// Remove the key
	delete(existing, key)

	// Write back
	return cw.writeConfig(existing)
}

// readConfig reads the current configuration as a map
func (cw *ConfigWriter) readConfig() (map[string]string, error) {
	config := make(map[string]string)

	data, err := os.ReadFile(cw.configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return config, nil
		}
		return nil, err
	}

	// Simple line-by-line parsing (key=value format)
	for _, line := range splitLines(string(data)) {
		line = trimSpace(line)
		if line == "" || line[0] == '#' {
			continue
		}
		parts := splitN(line, "=", 2)
		if len(parts) == 2 {
			config[trimSpace(parts[0])] = trimSpace(parts[1])
		}
	}

	return config, nil
}

// writeConfig writes the configuration map to the file
func (cw *ConfigWriter) writeConfig(config map[string]string) error {
	var lines []string
	for key, value := range config {
		lines = append(lines, key+"="+value)
	}

	data := joinLines(lines)
	return os.WriteFile(cw.configPath, []byte(data), 0644)
}

// serializeConfig converts a Config struct to bytes (placeholder)
func serializeConfig(config *Config) ([]byte, error) {
	// Placeholder implementation
	return []byte(""), nil
}

// Helper functions

func splitLines(s string) []string {
	var lines []string
	var current string
	for _, r := range s {
		if r == '\n' {
			lines = append(lines, current)
			current = ""
		} else {
			current += string(r)
		}
	}
	if current != "" {
		lines = append(lines, current)
	}
	return lines
}

func joinLines(lines []string) string {
	result := ""
	for i, line := range lines {
		if i > 0 {
			result += "\n"
		}
		result += line
	}
	return result
}

func splitN(s string, sep string, n int) []string {
	var parts []string
	for i := 0; i < n-1 && len(s) > 0; i++ {
		idx := indexOf(s, sep)
		if idx == -1 {
			break
		}
		parts = append(parts, s[:idx])
		s = s[idx+len(sep):]
	}
	parts = append(parts, s)
	return parts
}

func indexOf(s string, substr string) int {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return i
		}
	}
	return -1
}

func trimSpace(s string) string {
	start := 0
	end := len(s)
	for start < end && (s[start] == ' ' || s[start] == '\t') {
		start++
	}
	for end > start && (s[end-1] == ' ' || s[end-1] == '\t') {
		end--
	}
	return s[start:end]
}

