package main

import (
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

func check(e error) {
	if e != nil {
		panic(e)
	}
}

func pasteHandler(w http.ResponseWriter, req *http.Request) {
	if req.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	buf, err := io.ReadAll(req.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}
	defer req.Body.Close()

	// Ensure the buffer has enough data to slice safely
	if len(buf) < 135 {
		http.Error(w, "Invalid paste data", http.StatusBadRequest)
		return
	}

	// Extract the paste content based on the original logic
	// Original: buf[89 : len(buf)-46]
	paste := buf[89 : len(buf)-46]

	// Sanitize filename to prevent directory traversal
	filename := fmt.Sprintf("paste_%d.txt", len(paste))
	dir := "/tmp"
	// Ensure directory exists
	if err := os.MkdirAll(dir, 0755); err != nil {
		http.Error(w, "Server error", http.StatusInternalServerError)
		return
	}

	filePath := filepath.Join(dir, filename)
	err = os.WriteFile(filePath, paste, 0644)
	if err != nil {
		http.Error(w, "Failed to write file", http.StatusInternalServerError)
		return
	}

	// Return success with the file path or a simple message
	w.Header().Set("Content-Type", "text/plain")
	fmt.Fprintf(w, "Paste saved successfully to %s", filePath)
}

func main() {
	http.HandleFunc("/", pasteHandler)
	fmt.Println("Server starting on :8080")
	err := http.ListenAndServe(":8080", nil)
	if err != nil {
		fmt.Printf("Server failed to start: %v\n", err)
	}
}
