```go
package piglatin

import "strings"

func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, word := range words {
		words[i] = Translate(word)
	}
	return strings.Join(words, " ")
}

func Translate(word string) string {
	if startsWithVowel(word) ||
		strings.HasPrefix(word, "xr") ||
		strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Find the index of the first vowel sound
	index := findVowelIndex(word)
	if index == 0 {
		return word + "ay"
	}

	return word[index:] + word[:index] + "ay"
}

func startsWithVowel(word string) bool {
	return strings.HasPrefix(word, "a") ||
		strings.HasPrefix(word, "e") ||
		strings.HasPrefix(word, "i") ||
		strings.HasPrefix(word, "o") ||
		strings.HasPrefix(word, "u")
}

func findVowelIndex(word string) int {
	vowels := "aeiou"
	for i, char := range word {
		if strings.ContainsRune(vowels, char) {
			// Special case: "qu" is treated as a consonant cluster
			if char == 'u' && i > 0 && word[i-1] == 'q' {
				continue
			}
			return i
		}
	}
	return len(word)
}
