// No license is given for the use of this source code.

// This package impliments a basic LISP interpretor for embedding in a go program for scripting.
// This file provides a repl
package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/steelseries/golisp"
)

func main() {
	// If files are provided on the command line, evaluate them and exit
	if len(os.Args) > 1 {
		for _, filename := range os.Args[1:] {
			data, err := os.ReadFile(filename)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error reading file %s: %s\n", filename, err)
				os.Exit(1)
			}
			code, err := golisp.Parse(string(data))
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error parsing file %s: %s\n", filename, err)
				os.Exit(1)
			}
			d, err := golisp.Eval(code)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error evaluating file %s: %s\n", filename, err)
				os.Exit(1)
			} else {
				fmt.Printf("==> %s\n", golisp.String(d))
			}
		}
		return
	}

	// Otherwise, start the REPL
	in := bufio.NewReader(os.Stdin)
	for {
		fmt.Print("> ")
		input, err := in.ReadString('\n')
		if err != nil {
			// EOF or other error
			break
		}
		input = strings.TrimRight(input, "\r\n")
		if input == "" {
			continue
		}
		code, err := golisp.Parse(input)
		if err != nil {
			fmt.Printf("Error: %s\n", err)
			continue
		}
		d, err := golisp.Eval(code)
		if err != nil {
			fmt.Printf("Error in evaluation: %s\n", err)
		} else {
			fmt.Printf("==> %s\n", golisp.String(d))
		}
	}
}
