	envelopeTypes := []proto.LogMessage_EventType{
		proto.LogMessage_START,
		proto.LogMessage_STOP,
	}

	msgChan, errorChan := consumer.Firehose(firehoseSubscriptionId, authToken, envelopeTypes...)
	go func() {
		for err := range errorChan {
			fmt.Fprintf(os.Stderr, "%v\n", err.Error())
		}
	}()

	for msg := range msgChan {
		// Filter messages based on envelope type if not already filtered by the client
		if msg.GetEnvelope().GetType() == proto.Envelope_LOG_MESSAGE {
			logMsg := msg.GetEnvelope().GetLogMessage()
			fmt.Printf("[Event: %v] App: %v, Message: %v\n",
				logMsg.GetEventType(),
				logMsg.GetAppId(),
				logMsg.GetPayload())
		} else {
			fmt.Printf("%v \n", msg)
		}
	}
}

