		if err != nil {
			return modules, fmt.Errorf("failed to read modules configuration file %s: %w", path, err)
		}
		if err := json.Unmarshal(data, &modules); err != nil {
			return modules, fmt.Errorf("failed to parse modules configuration file %s: %w", path, err)
		}
		for i, _ := range modules {
			if modules[i].Form == "" {
				modules[i].Form = "git"
			}
		}
	}
	return modules, nil
}
