	}

	if string(data) != filecontents {
		t.Errorf("Encrypt Decrypt returned bad results!\n Expected: %v \n Got: %v", filecontents, data)
	}
}

func TestEncryptDecryptLargeFile(t *testing.T) {
	// Create a larger file to test with
	largeContents := make([]byte, 1024*1024) // 1MB
	if _, err := rand.Read(largeContents); err != nil {
		t.Fatalf("Error generating random data: %v", err)
	}

	if err := ioutil.WriteFile(filetestpath, largeContents, os.FileMode(0644)); err != nil {
		t.Errorf("Error writing test file to %s: %v", filetestpath, err)
	}

	EncryptFile(filetestpath, passphrase)
	CheckEncryption(filetestpath)
	DecryptFile(filetestpath, passphrase)

	data, err := ioutil.ReadFile(filetestpath)
	if err != nil {
		t.Errorf("[ERR] Unable to read testfile: %v", err)
	}

	if len(data) != len(largeContents) {
		t.Errorf("Encrypt Decrypt returned bad results!\n Expected length: %v \n Got length: %v", len(largeContents), len(data))
	}

	for i := range largeContents {
		if data[i] != largeContents[i] {
			t.Errorf("Data mismatch at index %d: Expected %v, Got %v", i, largeContents[i], data[i])
			break
		}
	}
}

func TestEncryptDecryptEmptyFile(t *testing.T) {
	// Create an empty file
	if err := ioutil.WriteFile(filetestpath, []byte(""), os.FileMode(0644)); err != nil {
		t.Errorf("Error writing test file to %s: %v", filetestpath, err)
	}

	EncryptFile(filetestpath, passphrase)
	CheckEncryption(filetestpath)
	DecryptFile(filetestpath, passphrase)

	data, err := ioutil.ReadFile(filetestpath)
	if err != nil {
		t.Errorf("[ERR] Unable to read testfile: %v", err)
	}

	if string(data) != "" {
		t.Errorf("Encrypt Decrypt returned bad results!\n Expected: %v \n Got: %v", "", data)
	}
}

func TestEncryptDecryptSpecialCharacters(t *testing.T) {
	// Create a file with special characters
	specialContents := "Hello, 世界! 🌍\n\t\r\n"

	if err := ioutil.WriteFile(filetestpath, []byte(specialContents), os.FileMode(0644)); err != nil {
		t.Errorf("Error writing test file to %s: %v", filetestpath, err)
	}

	EncryptFile(filetestpath, passphrase)
	CheckEncryption(filetestpath)
	DecryptFile(filetestpath, passphrase)

	data, err := ioutil.ReadFile(filetestpath)
	if err != nil {
		t.Errorf("[ERR] Unable to read testfile: %v", err)
	}

	if string(data) != specialContents {
		t.Errorf("Encrypt Decrypt returned bad results!\n Expected: %v \n Got: %v", specialContents, data)
	}
}

func TestEncryptDecryptNonExistentFile(t *testing.T) {
	// Test with a non-existent file
	nonExistentPath := "/tmp/nonexistentfile12345"

	// Encrypt should handle non-existent file gracefully or fail appropriately
	// Depending on implementation, this might panic or return an error
	// For this test, we assume EncryptFile handles it or we expect it to fail
	defer func() {
		if r := recover(); r != nil {
			t.Logf("EncryptFile panicked on non-existent file as expected: %v", r)
		}
	}()

	EncryptFile(nonExistentPath, passphrase)
}

func TestDecryptWrongPassphrase(t *testing.T) {
	// Write a temp file
	if err := ioutil.WriteFile(filetestpath, []byte(filecontents), os.FileMode(0644)); err != nil {
		t.Errorf("Error writing test file to %s: %v", filetestpath, err)
	}

	EncryptFile(filetestpath, passphrase)
	CheckEncryption(filetestpath)

	// Try to decrypt with wrong passphrase
	DecryptFile(filetestpath, "wrongpassphrase")

	data, err := ioutil.ReadFile(filetestpath)
	if err != nil {
		t.Errorf("[ERR] Unable to read testfile: %v", err)
	}

	// The decrypted data should not match the original if decryption failed
	// Note: This depends on implementation. Some implementations might still return data but it will be garbage.
	if string(data) == filecontents {
		t.Errorf("Decrypt with wrong passphrase should not return original data")
	}
}
