```go
package main

import (
	"os"
	"strings"
)

func init() {
	home := os.Getenv("HOME")
	paths := []string{
		home + "/bin",
		home + "/.vvmn/vim/current/bin",
		"/usr/local/bin",
		"/usr/local/opt/coreutils/libexec/gnubin",
	}
	setPath(paths...)
}

func setPath(args ...string) {
	currentPath := os.Getenv("PATH")
	if currentPath == "" {
		os.Setenv("PATH", strings.Join(args, ":"))
		return
	}

	// Split existing PATH into a map for quick lookup
	existingPaths := strings.Split(currentPath, ":")
	existingMap := make(map[string]bool)
	for _, p := range existingPaths {
		if p != "" {
			existingMap[p] = true
		}
	}

	// Build new PATH: new args first, then existing paths not already included
	var newPaths []string
	for _, arg := range args {
		if arg != "" {
			newPaths = append(newPaths, arg)
		}
	}
	for _, p := range existingPaths {
		if p != "" && !existingMap[p] {
			newPaths = append(newPaths, p)
		}
	}

	os.Setenv("PATH", strings.Join(newPaths, ":"))
}
