```go
package binstore

import (
	"bytes"
	"sync"

	"github.com/boltdb/bolt"
)

// BoltDB store.
type BoltDB struct {
	db   *bolt.DB
	mu   sync.RWMutex
	bucket []byte
}

// NewBoltDB creates a new BoltDB backend.
func NewBoltDB(path string, bucket []byte) (*BoltDB, error) {
	db, err := bolt.Open(path, 0600, nil)
	if err != nil {
		return nil, err
	}

	// Ensure the bucket exists
	err = db.Update(func(tx *bolt.Tx) error {
		_, err := tx.CreateBucketIfNotExists(bucket)
		return err
	})
	if err != nil {
		db.Close()
		return nil, err
	}

	return &BoltDB{
		db:     db,
		bucket: bucket,
	}, nil
}

// Get retrieves a value by key.
func (b *BoltDB) Get(key []byte) ([]byte, error) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	var val []byte
	err := b.db.View(func(tx *bolt.Tx) error {
		bucket := tx.Bucket(b.bucket)
		if bucket == nil {
			return ErrNotFound
		}
		val = bucket.Get(key)
		if val == nil {
			return ErrNotFound
		}
		val = append([]byte(nil), val...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return val, nil
}

// Put stores a value by key.
func (b *BoltDB) Put(key []byte, value []byte) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	return b.db.Update(func(tx *bolt.Tx) error {
		bucket := tx.Bucket(b.bucket)
		if bucket == nil {
			return ErrBucketNotFound
		}
		return bucket.Put(key, value)
	})
}

// Delete removes a key.
func (b *BoltDB) Delete(key []byte) error {
	b.mu.Lock()
	defer b.mu.Unlock()

	return b.db.Update(func(tx *bolt.Tx) error {
		bucket := tx.Bucket(b.bucket)
		if bucket == nil {
			return ErrBucketNotFound
		}
		return bucket.Delete(key)
	})
}

// Close closes the database.
func (b *BoltDB) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.db.Close()
}

// Keys returns all keys in the bucket.
func (b *BoltDB) Keys() ([][]byte, error) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	var keys [][]byte
	err := b.db.View(func(tx *bolt.Tx) error {
		bucket := tx.Bucket(b.bucket)
		if bucket == nil {
			return ErrBucketNotFound
		}
		return bucket.ForEach(func(k, v []byte) error {
			keys = append(keys, append([]byte(nil), k...))
			return nil
		})
	})
	if err != nil {
		return nil, err
	}
	return keys, nil
}

// Exists checks if a key exists.
func (b *BoltDB) Exists(key []byte) (bool, error) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	var exists bool
	err := b.db.View(func(tx *bolt.Tx) error {
		bucket := tx.Bucket(b.bucket)
		if bucket == nil {
			return ErrBucketNotFound
		}
		exists = bucket.Get(key) != nil
		return nil
	})
	if err != nil {
		return false, err
	}
	return exists, nil
}

// ErrNotFound is returned when a key is not found.
var ErrNotFound = fmt.Errorf("key not found")

// ErrBucketNotFound is returned when the bucket does not exist.
var ErrBucketNotFound = fmt.Errorf("bucket not found")
