```go
package thrift

import (
	"log"
	"os"

	"github.com/uber-go/tally"
	"github.com/uber-go/tally/statsd"
)

var (
	Metrics *Metric = NewMetric(os.Getenv("STATSD_URL"))
)

type Metric struct {
	scope tally.Scope
}

func NewMetric(statsdURL string) *Metric {
	if statsdURL == "" {
		return &Metric{scope: tally.NoopScope}
	}

	reporter, err := statsd.NewReporter(statsd.Options{
		Address:     statsdURL,
		Prefix:      "thrift",
		SampleRate:  1.0,
	})
	if err != nil {
		log.Println(err.Error())
		return &Metric{scope: tally.NoopScope}
	}

	scope, err := tally.NewScope(tally.ScopeOptions{
		CacheTime:     0,
		Prefix:        "thrift",
		TagOptions:    nil,
		Reporter:      reporter,
	}, nil)
	if err != nil {
		log.Println(err.Error())
		return &Metric{scope: tally.NoopScope}
	}

	return &Metric{scope: scope}
}

func (m *Metric) Incr(metricName string) {
	if m.scope != nil {
		m.scope.Counter(metricName).Inc(1)
	}
}

func (m *Metric) Timing(metricName string, duration int64) {
	if m.scope != nil {
		m.scope.Timer(metricName).RecordDuration(duration)
	}
}
