package proof

import (
	"hash"
	"io"
)

type Reader32 struct {
	r   io.Reader
	h   hash.Hash32
	sum uint32
}

func NewReader32(r io.Reader, h hash.Hash32, sum uint32) *Reader32 {
	return &Reader32{
		r:   r,
		h:   h,
		sum: sum,
	}
}

func (r *Reader32) Read(p []byte) (int, error) {
	n, err := r.r.Read(p)
	if n > 0 {
		r.h.Write(p[:n])
	}
	if err == nil || err == io.EOF {
		r.sum = r.h.Sum32()
	}
	return n, err
}
