	LoadSpec
	WriteLoadSpec
	ReadLoadSpec
	UpdateLoadSpec
}

func (gls GateLoadSpec) Validate() error {

	if err := gls.LoadSpec.Validate(); err != nil {
		return err
	}

	if err := gls.ReadLoadSpec.Validate(); err != nil {
		return err
	}

	if err := gls.WriteLoadSpec.Validate(); err != nil {
		return err
	}

	if err := gls.UpdateLoadSpec.Validate(); err != nil {
		return err
	}

	if gls.WriteLoadSpec.Writers < gls.UpdateLoadSpec.Updaters {
		return errors.New("number of writers must be at least as many as updaters")
	}

	return nil
}

