```go
/* Demonstrate a streaming REST API, where the data is "flushed" to the client ASAP.

The Curl Demo:

        curl -i http://127.0.0.1:8080/stream

*/
package main

import (
	"encoding/json"
	"fmt"
	"github.com/ant0ine/go-json-rest"
	"net/http"
	"time"
)

func main() {

	handler := rest.ResourceHandler{
		EnableRelaxedContentType: true,
	}
	handler.SetRoutes(
		rest.Route{"GET", "/stream", StreamThings},
	)
	http.ListenAndServe(":8080", &handler)
}

type Thing struct {
	Name string `json:"name"`
}

func StreamThings(w *rest.ResponseWriter, r *rest.Request) {
	cpt := 0
	for {
		cpt++
		thing := Thing{
			Name: fmt.Sprintf("thing #%d", cpt),
		}
		// Marshal to JSON manually to append newline for Line Delimited JSON
		jsonBytes, err := json.Marshal(thing)
		if err != nil {
			w.WriteJson(map[string]string{"error": err.Error()})
			w.Flush()
			return
		}
		// Write the JSON object followed by a newline
		w.Write([]byte(string(jsonBytes) + "\n"))
		// Flush the buffer to client
		w.Flush()
		// wait 3 seconds
		time.Sleep(time.Duration(3) * time.Second)
	}
}
