```go
package gstrings

import (
	"github.com/wallclockbuilder/testify/assert"
	"testing"
)

// Empty checks if a value is "empty". Zero value for most types, nil pointers, empty slices, maps, etc.
//
// Examples:
//
//	Empty("")        // true
//	Empty(" ")       // false
//	Empty("hello")   // false
//	Empty([]int{})   // true
//	Empty(nil)       // true
func Empty(t *testing.T, value interface{}, msgAndArgs ...interface{}) bool {
	if isNil(value) {
		return true
	}
	switch v := value.(type) {
	case string:
		return len(v) == 0
	case []byte:
		return len(v) == 0
	case []int:
		return len(v) == 0
	case []string:
		return len(v) == 0
	case map[string]interface{}:
		return len(v) == 0
	default:
		// For other types, we consider them non-empty if they are not nil
		return false
	}
}

func isNil(i interface{}) bool {
	if i == nil {
		return true
	}
	switch v := i.(type) {
	case reflect.Value:
		return !v.IsValid()
	default:
		return false
	}
}

func TestEmpty(t *testing.T) {
	assert := assert.New(t)
	assert.Equal(false, Empty("hello"))
	assert.Equal(false, Empty(" "))
	assert.Equal(true, Empty(""))
}
