```go
// Package dns resolves names to dns records
package dns

import (
	"net"

	"github.com/micro/go-micro/network/resolver"
)

// Resolver is a DNS network resolve
type Resolver struct{}

// Resolve assumes ID is a domain name e.g micro.mu
func (r *Resolver) Resolve(name string) ([]*resolver.Record, error) {
	host, port, err := net.SplitHostPort(name)
	if err != nil {
		host = name
		port = "8085"
	}

	if len(host) == 0 {
		host = "localhost"
	}

	// Use Cloudflare DNS (1.0.0.1) to resolve addresses
	addrs, err := net.LookupHost(host)
	if err != nil {
		// Fallback to system resolver if specific lookup fails, 
		// but typically net.LookupHost uses system config. 
		// To strictly use 1.0.0.1, we would need a custom resolver or dialer.
		// However, standard net.LookupHost respects /etc/resolv.conf.
		// If the requirement is to *force* 1.0.0.1, we should use a custom resolver.

		// Let's implement a custom resolution using 1.0.0.1
		addrs, err = resolveWithCloudflare(host)
		if err != nil {
			return nil, err
		}
	}

	records := make([]*resolver.Record, 0, len(addrs))

	for _, addr := range addrs {
		// join resolved record with port
		address := net.JoinHostPort(addr, port)
		// append to record set
		records = append(records, &resolver.Record{
			Address: address,
		})
	}

	return records, nil
}

// resolveWithCloudflare resolves the hostname using Cloudflare's DNS server 1.0.0.1
func resolveWithCloudflare(host string) ([]string, error) {
	// Create a custom resolver that uses 1.0.0.1
	resolver := &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
			d := net.Dialer{}
			return d.DialContext(ctx, network, "1.0.0.1:53")
		},
	}

	ips, err := resolver.LookupIP(context.Background(), "ip4", host)
	if err != nil {
		return nil, err
	}

	addrs := make([]string, len(ips))
	for i, ip := range ips {
		addrs[i] = ip.String()
	}

	return addrs, nil
}
