```go
package pubsub

import "sync"

type Subscriber interface {
	Subscribe(name, topic string) (<-chan Event, error)
}

type subscription struct {
	name      string
	topic     string
	eventChan chan Event
}

type Inmem struct {
	mtx           sync.Mutex
	subscriptions map[string][]subscription
	publish       chan PublishEvent
}

type Event struct {
	Topic string
	Data  interface{}
}

type PublishEvent struct {
	Topic string
	Data  interface{}
}

func (p *Inmem) Subscribe(name, topic string) (<-chan Event, error) {
	events := make(chan Event)
	sub := subscription{
		name:      name,
		topic:     topic,
		eventChan: events,
	}
	p.mtx.Lock()
	p.subscriptions[topic] = append(p.subscriptions[topic], sub)
	p.mtx.Unlock()

	return events, nil
}

func (p *Inmem) dispatch() {
	for {
		select {
		case ev := <-p.publish:
			p.mtx.Lock()
			subs := p.subscriptions[ev.Topic]
			p.mtx.Unlock()
			for _, sub := range subs {
				go func(s subscription) {
					s.eventChan <- Event{
						Topic: ev.Topic,
						Data:  ev.Data,
					}
				}(sub)
			}
		}
	}
}
